 sealed class Fixture:IDisposable {
  readonly SqliteConnection connection=new("Data Source=:memory:");
  public readonly AppDbContext App;
  public readonly OrdersDbContext Orders=new(new DbContextOptionsBuilder<OrdersDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options,null);
  public readonly AccountingDbContext Accounting=new(new DbContextOptionsBuilder<AccountingDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options,null);
  public readonly CatalogDbContext Catalog=new(new DbContextOptionsBuilder<CatalogDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options,null);
  public readonly Mock<UserManager<AppUser>> Users=new(new Mock<IUserStore<AppUser>>().Object,null,null,null,null,null,null,null,null);
  public readonly AppUser User=new(){Id=Guid.NewGuid(),FirstName="Old",LastName="Driver",FullName="Old Driver",UserName="+963940722840",PhoneNumber="+963940722840",CountryPhoneCode="+963",IsActive=true,DefaultLat=34.7m,DefaultLng=36.7m,Birthday=new DateTime(1994,1,1),Lang="tr",CaptainCompensationType=CaptainCompensationType.Percentage,CaptainRate=40m};
  public readonly LedgerService Ledger;
  public Fixture() {
   connection.Open(); App=new(new DbContextOptionsBuilder<AppDbContext>().UseSqlite(connection).Options,null);App.Database.EnsureCreated();
   App.Users.Add(User);
   foreach(var role in new[]{AppRoleName.Customer,AppRoleName.Delivery,AppRoleName.Merchant,AppRoleName.Admin})App.Roles.Add(new(){Id=Guid.NewGuid(),Name=role.ToString(),NormalizedName=role.ToString().ToUpperInvariant()});App.SaveChanges();
   AddRole(User,AppRoleName.Delivery);AddRole(User,AppRoleName.Customer);
   Ledger=new(Accounting,NullLogger<LedgerService>.Instance);
   Users.SetupGet(x=>x.Users).Returns(App.Users);
   Users.Setup(x=>x.FindByIdAsync(It.IsAny<string>())).ReturnsAsync((string id)=>App.Users.SingleOrDefault(u=>u.Id.ToString()==id));
   Users.Setup(x=>x.GetUserAsync(It.IsAny<ClaimsPrincipal>())).ReturnsAsync(User);
   Users.Setup(x=>x.GetRolesAsync(It.IsAny<AppUser>())).ReturnsAsync((AppUser user)=>(IList<string>)App.UserRoles.Where(r=>r.UserId==user.Id).Join(App.Roles,r=>r.RoleId,r=>r.Id,(ur,r)=>r.Name).ToList());
   Users.Setup(x=>x.IsInRoleAsync(It.IsAny<AppUser>(),It.IsAny<string>())).ReturnsAsync((AppUser user,string role)=>App.UserRoles.Any(ur=>ur.UserId==user.Id && App.Roles.Any(r=>r.Id==ur.RoleId && r.Name==role)));
   Users.Setup(x=>x.UpdateAsync(It.IsAny<AppUser>())).Returns(async()=>{await App.SaveChangesAsync();return IdentityResult.Success;});
   Users.Setup(x=>x.AddToRoleAsync(It.IsAny<AppUser>(),It.IsAny<string>())).ReturnsAsync((AppUser user,string role)=>{App.UserRoles.Add(new(){UserId=user.Id,RoleId=App.Roles.Single(r=>r.Name==role).Id});App.SaveChanges();return IdentityResult.Success;});
   Users.Setup(x=>x.RemoveFromRolesAsync(It.IsAny<AppUser>(),It.IsAny<IEnumerable<string>>())).ReturnsAsync((AppUser user,IEnumerable<string> roles)=>{App.UserRoles.RemoveRange(App.UserRoles.Where(ur=>ur.UserId==user.Id && App.Roles.Any(r=>r.Id==ur.RoleId && roles.Contains(r.Name))));App.SaveChanges();return IdentityResult.Success;});
  }
  public void AddRole(AppUser user,AppRoleName role){App.UserRoles.Add(new(){UserId=user.Id,RoleId=App.Roles.Single(r=>r.Name==role.ToString()).Id});App.SaveChanges();}
  public UserDto Request(AppRoleName role=AppRoleName.Delivery)=>new(){FirstName="New",LastName="Driver",PhoneNumber="940722840",CountryPhoneCode="+963",Role=role,IsActive=true,Lang="ar",MaxCashFloat=10000m,CaptainCompensationType=CaptainCompensationType.Percentage,CaptainRate=40m};
  public AdminUsers Controller(IAdminAuditService audit=null,INotificationService notifications=null)=>new(Users.Object,null,null,new AppUnitOfWork(App),null,null,NullLogger<AdminUsers>.Instance,null,null,null,audit,notifications,Accounting,Orders,Catalog,Ledger);
  public NotificationService Notifications() {
   var repo=new Mock<INotificationMessageRepo>();repo.Setup(r=>r.Queryable()).Returns(App.Set<NotificationMessage>());
   repo.Setup(r=>r.Update(It.IsAny<NotificationMessage>())).Callback<NotificationMessage>(n=>App.Update(n));
   return new(new TrackableRepository<Notification,AppDbContext>(App),repo.Object,Options.Create(new SolAppOptions{DefaultLanguage="ar",SupportedLanguages=new[]{"ar"}}),Options.Create(new NotificationOptions{UserTopicSalt="qa"}),null,Users.Object,new AppUnitOfWork(App),null,NullLogger<NotificationService>.Instance);
  }
  public void Dispose(){App.Dispose();connection.Dispose();Accounting.Dispose();Orders.Dispose();Catalog.Dispose();}
 }
 static JsonElement Json(object value)=>JsonSerializer.SerializeToElement(value,new JsonSerializerOptions{PropertyNamingPolicy=JsonNamingPolicy.CamelCase});
