 [Fact]public async Task ProfileEditPreservesCoordinatesBirthdayAndCustomerRole(){using var f=new Fixture();var birthday=f.User.Birthday;var result=await f.Controller().Edit(f.User.Id,f.Request());Assert.Equal(f.User.Id,result.Value);Assert.Equal(34.7m,f.User.DefaultLat);Assert.Equal(36.7m,f.User.DefaultLng);Assert.Equal(birthday,f.User.Birthday);Assert.Equal("ar",f.User.Lang);Assert.Equal(40m,f.User.CaptainRate);Assert.Equal(2,(await f.Users.Object.GetRolesAsync(f.User)).Count);f.Users.Verify(u=>u.RemoveFromRolesAsync(It.IsAny<AppUser>(),It.IsAny<IEnumerable<string>>()),Times.Never);}
 [Fact]public async Task PartialPayloadCannotExceedExistingPercentage(){using var f=new Fixture();var request=f.Request();request.CaptainCompensationType=null;request.CaptainRate=101m;Assert.IsType<BadRequestObjectResult>((await f.Controller().Edit(f.User.Id,request)).Result);Assert.Equal(40m,f.User.CaptainRate);}
 [Theory][InlineData("cash")][InlineData("earnings")][InlineData("reservation")][InlineData("order")][InlineData("errand")]
 public async Task DriverRoleCannotChangeWhileFinancialOrDeliveryObligationsRemain(string scenario){
  using var f=new Fixture();
  if(scenario=="cash" || scenario=="earnings") {var account=await f.Ledger.GetOrCreateUserAccountAsync(f.User.Id,scenario=="cash"?AccountType.Asset:AccountType.Liability,scenario=="cash"?SystemAccountCodes.CaptainCashFloatPrefix:SystemAccountCodes.CaptainEarningsPrefix,"Driver");var offset=await f.Ledger.GetOrCreateSystemAccountAsync("QA", "Opening", scenario=="cash"?AccountType.Equity:AccountType.Expense);await f.Ledger.PostTransactionAsync(new(){IdempotencyKey="seed",Entries=new(){new(){AccountId=account.Id,Debit=scenario=="cash"?1m:0m,Credit=scenario=="earnings"?1m:0m},new(){AccountId=offset.Id,Credit=scenario=="cash"?1m:0m,Debit=scenario=="earnings"?1m:0m}}});}
  if(scenario=="reservation"){f.Accounting.SettlementRequests.Add(new(){Id=Guid.NewGuid(),RequestedByUserId=f.User.Id,Status=SettlementRequestStatus.Pending,RequestNumber="qa",Currency="SYP",Amount=0m});await f.Accounting.SaveChangesAsync();}
  if(scenario=="order"){f.Orders.Orders.Add(new(){Id=1,DeliveryId=f.User.Id,OrderStatus=OrderStatus.Success,OrderDetails=new List<OrderDetail>{new(){OrderDetailStatus=OrderDetailStatus.MerchantAccepted}}});await f.Orders.SaveChangesAsync();}
  if(scenario=="errand"){f.App.SupportMessages.Add(new(){Title="Purchase",ErrandDriverUserId=f.User.Id,ErrandStatus=ErrandStatus.Assigned});await f.App.SaveChangesAsync();}
  Assert.IsType<BadRequestObjectResult>((await f.Controller().Edit(f.User.Id,f.Request(AppRoleName.Customer))).Result);Assert.Contains("Delivery",await f.Users.Object.GetRolesAsync(f.User));Assert.Equal(40m,f.User.CaptainRate);Assert.IsType<BadRequestObjectResult>((await f.Controller().Delete(f.User.Id)).Result);Assert.Null(f.User.DeletionDate);
 }
 [Fact]public async Task MerchantOwnershipPreventsRoleChange(){using var f=new Fixture();f.AddRole(f.User,AppRoleName.Merchant);f.Catalog.Merchants.Add(new(){Id=30,OwnerId=f.User.Id,Title="Store"});await f.Catalog.SaveChangesAsync();Assert.IsType<BadRequestObjectResult>((await f.Controller().Edit(f.User.Id,f.Request(AppRoleName.Customer))).Result);Assert.IsType<BadRequestObjectResult>((await f.Controller().Delete(f.User.Id)).Result);}
 [Fact]public async Task FailedRoleRemovalRollsBackProfileAndAddedRole(){using var f=new Fixture();f.Users.Setup(u=>u.RemoveFromRolesAsync(It.IsAny<AppUser>(),It.IsAny<IEnumerable<string>>())).ReturnsAsync(IdentityResult.Failed(new IdentityError{Description="Role error"}));Assert.IsType<BadRequestObjectResult>((await f.Controller().Edit(f.User.Id,f.Request(AppRoleName.Merchant))).Result);f.App.ChangeTracker.Clear();var user=await f.App.Users.SingleAsync();Assert.Equal("Old Driver",user.FullName);Assert.Equal("tr",user.Lang);Assert.DoesNotContain("Merchant",await f.Users.Object.GetRolesAsync(user));Assert.Contains("Delivery",await f.Users.Object.GetRolesAsync(user));}
 [Fact]public async Task FailedPasswordResetRollsBackProfile(){using var f=new Fixture();f.Users.Setup(u=>u.GeneratePasswordResetTokenAsync(It.IsAny<AppUser>())).ReturnsAsync("token");f.Users.Setup(u=>u.ResetPasswordAsync(It.IsAny<AppUser>(),"token","abcdef")).ReturnsAsync(IdentityResult.Failed(new IdentityError{Description="Password error"}));var request=f.Request();request.Password="abcdef";Assert.IsType<BadRequestObjectResult>((await f.Controller().Edit(f.User.Id,request)).Result);f.App.ChangeTracker.Clear();Assert.Equal("Old Driver",(await f.App.Users.SingleAsync()).FullName);}
