 [Fact]public async Task AuditAndDisablePushFailureDoNotUndoSuccessfulEdit(){using var f=new Fixture();var audit=new Mock<IAdminAuditService>();audit.Setup(a=>a.LogAsync(It.IsAny<AdminAuditLogEntry>())).ThrowsAsync(new Exception("Audit unavailable"));var notifications=new Mock<INotificationService>();notifications.Setup(n=>n.SendPushNotification(It.IsAny<Notification>(),It.IsAny<Guid[]>(),It.IsAny<bool>(),It.IsAny<bool>())).ThrowsAsync(new Exception("Push unavailable"));var request=f.Request();request.IsActive=false;Assert.Equal(f.User.Id,(await f.Controller(audit.Object,notifications.Object).Edit(f.User.Id,request)).Value);Assert.False(f.User.IsActive);}
 [Fact]public async Task UsersSummaryAndFiltersCoverAllPagesAndExcludeDualRoleAdmin(){using var f=new Fixture();for(int i=0;i<4;i++){var u=new AppUser{Id=Guid.NewGuid(),FullName="Customer "+i,IsActive=i<3,Lang="en"};f.App.Users.Add(u);f.App.SaveChanges();f.AddRole(u,AppRoleName.Customer);if(i==2)f.AddRole(u,AppRoleName.Admin);}var c=f.Controller();var data=Json(Assert.IsType<OkObjectResult>((await c.DataTable(new(){PageNumber=1,PageSize=1},AppRoleName.Customer,true)).Result).Value);Assert.Equal(2,data.GetProperty("totalRecords").GetInt32());Assert.Equal(2,data.GetProperty("summary").GetProperty("active").GetInt32());Assert.Equal("en",data.GetProperty("items")[0].GetProperty("lang").GetString());Assert.Equal(1,data.GetProperty("items").GetArrayLength());}
 [Fact]public async Task ReviewPagesFiltersStatisticsAndFullNameSearchStayConsistent(){using var f=new Fixture();f.Orders.MerchantReviews.AddRange(Enumerable.Range(1,4).Select(i=>new MerchantReview{Id=i,OrderId=i,MerchantId=30,ReviewerId=f.User.Id,Rate=i==1?1:5,CreatedDate=DateTime.UtcNow.Date,TextReview=i==1?"Low":null}));await f.Orders.SaveChangesAsync();var merchants=new Mock<IMerchantService>();merchants.Setup(m=>m.Queryable()).Returns(f.Catalog.Merchants);var controller=new MerchantReviewsController(new OrdersUnitOfWork(f.Orders),merchants.Object,new AppUnitOfWork(f.App));var a=Json(Assert.IsType<OkObjectResult>((await controller.DataTable(new(){PageNumber=1,PageSize=1,Search="Old Driver"})).Result).Value);var b=Json(Assert.IsType<OkObjectResult>((await controller.DataTable(new(){PageNumber=2,PageSize=1})).Result).Value);Assert.Equal(4,a.GetProperty("totalRecords").GetInt32());Assert.Equal(4,a.GetProperty("summary").GetProperty("averageRating").GetDouble());Assert.Equal(3,a.GetProperty("summary").GetProperty("fiveStarCount").GetInt32());Assert.NotEqual(a.GetProperty("items")[0].GetProperty("id").GetInt32(),b.GetProperty("items")[0].GetProperty("id").GetInt32());Assert.Equal(f.User.Id,a.GetProperty("items")[0].GetProperty("reviewerId").GetGuid());var critical=Json(Assert.IsType<OkObjectResult>((await controller.DataTable(new(){PageNumber=1},"critical")).Result).Value);Assert.Equal(1,critical.GetProperty("totalRecords").GetInt32());}
 [Fact]public async Task RemovedRoleInvalidatesOldTokenImmediately(){using var f=new Fixture();var context=new DefaultHttpContext{User=new ClaimsPrincipal(new ClaimsIdentity(new[]{new Claim(ClaimTypes.Role,"Merchant")},"test"))};var called=false;await new App.Helpers.DisabledAccountMiddleware(_=>{called=true;return Task.CompletedTask;}).InvokeAsync(context,f.Users.Object);Assert.False(called);Assert.Equal(401,context.Response.StatusCode);}
 [Fact]public async Task CurrentRoleTokenStillWorks(){using var f=new Fixture();var context=new DefaultHttpContext{User=new ClaimsPrincipal(new ClaimsIdentity(new[]{new Claim(ClaimTypes.Role,"Delivery")},"test"))};var called=false;await new App.Helpers.DisabledAccountMiddleware(_=>{called=true;return Task.CompletedTask;}).InvokeAsync(context,f.Users.Object);Assert.True(called);}
 [Fact]public async Task NotificationPagesReadOnlyTheirOwnTwentyRecords(){using var f=new Fixture();var other=Guid.NewGuid();f.App.Users.Add(new(){Id=other,UserName="other",IsActive=true});for(int i=1;i<=25;i++)f.App.Notifications.Add(new(){Id=i,Topic="all",CreatedDate=DateTime.UtcNow.Date,NotificationType=NotificationType.GlobalNotification,NotificationMessages=new List<NotificationMessage>{new(){UserId=f.User.Id},new(){UserId=other}}});await f.App.SaveChangesAsync();var service=f.Notifications();Assert.Equal(20,(await service.GetNotifications(f.User.Id)).Length);Assert.Equal(5,(await service.GetNotifications(f.User.Id,page:1)).Length);Assert.Equal(0,await service.CountUnreadNotifications(f.User.Id));Assert.Equal(25,await service.CountUnreadNotifications(other));Assert.Equal(0,f.App.Notifications.Sum(n=>n.NotLoggedInReadCount));}
 [Fact]public async Task ReadAllAndReceivedDoNotTouchAnotherAccount(){using var f=new Fixture();var other=Guid.NewGuid();f.App.Users.Add(new(){Id=other,UserName="other",IsActive=true});f.App.Notifications.Add(new(){Id=1,Topic="all",NotificationType=NotificationType.GlobalNotification,NotificationMessages=new List<NotificationMessage>{new(){UserId=f.User.Id},new(){UserId=other}}});await f.App.SaveChangesAsync();var service=f.Notifications();await service.MarkAsRecived(f.User.Id,1);Assert.NotNull(f.App.Set<NotificationMessage>().Single(m=>m.UserId==f.User.Id).RecivedDate);Assert.Null(f.App.Set<NotificationMessage>().Single(m=>m.UserId==other).RecivedDate);await service.MarkAsRead(f.User.Id,null);Assert.Equal(0,await service.CountUnreadNotifications(f.User.Id));Assert.Equal(1,await service.CountUnreadNotifications(other));}
 [Fact]public async Task NewDriverDefaultsToSalaryWithoutInventingCommission(){using var f=new Fixture();f.Users.Setup(u=>u.CreateAsync(It.IsAny<AppUser>(),It.IsAny<string>())).ReturnsAsync((AppUser user,string password)=>{user.Id=Guid.NewGuid();f.App.Users.Add(user);f.App.SaveChanges();return IdentityResult.Success;});var request=f.Request();request.FirstName="  New  ";request.LastName="  Name  ";request.PhoneNumber="940722841";request.Password="abcdef";request.CaptainCompensationType=null;request.CaptainRate=40m;var result=await f.Controller().Create(request);Assert.Null(result.Result);var created=f.App.Users.Single(u=>u.Id==result.Value);Assert.Equal("New Name",created.FullName);Assert.Equal(CaptainCompensationType.SalariedEmployee,created.CaptainCompensationType);Assert.Equal(0m,created.CaptainRate);}
 [Fact]public async Task FailedNewRoleDoesNotLeaveAnOrphanAccount(){using var f=new Fixture();f.Users.Setup(u=>u.CreateAsync(It.IsAny<AppUser>(),It.IsAny<string>())).ReturnsAsync((AppUser user,string password)=>{user.Id=Guid.NewGuid();f.App.Users.Add(user);f.App.SaveChanges();return IdentityResult.Success;});f.Users.Setup(u=>u.AddToRoleAsync(It.IsAny<AppUser>(),It.IsAny<string>())).ReturnsAsync(IdentityResult.Failed(new IdentityError{Description="Failed"}));var request=f.Request();request.PhoneNumber="940722841";request.Password="abcdef";Assert.IsType<BadRequestObjectResult>((await f.Controller().Create(request)).Result);f.App.ChangeTracker.Clear();Assert.Single(f.App.Users);}
 [Fact]public async Task ArchivedSettledDriverKeepsHistoryAndRoles(){using var f=new Fixture();Assert.True((await f.Controller().Delete(f.User.Id)).Value);Assert.False(f.User.IsActive);Assert.NotNull(f.User.DeletionDate);Assert.Contains("Delivery",await f.Users.Object.GetRolesAsync(f.User));Assert.Single(f.App.Users);}
 [Fact]public async Task CampaignAuditFailureDoesNotInviteResending(){using var f=new Fixture();var service=new Mock<INotificationService>();service.Setup(x=>x.IsCampaignPushConfigured()).Returns(true);service.Setup(x=>x.SendCampaignNotification(It.IsAny<Notification>(),It.IsAny<Guid[]>())).ReturnsAsync(new CampaignPushResult{AcceptedLanguages=3,RecipientAccounts=1});f.Users.Setup(u=>u.GetUsersInRoleAsync("Customer")).ReturnsAsync(new List<AppUser>{f.User});var audit=new Mock<IAdminAuditService>();audit.Setup(a=>a.LogAsync(It.IsAny<AdminAuditLogEntry>())).ThrowsAsync(new Exception("Logging offline"));var c=new AdminNotifications(service.Object,f.Users.Object,null,audit.Object);var result=await c.Create(new(){Target="customers",TitleAr="رسالة مهمة",TextAr="نص إشعار للاختبار"});Assert.Equal(3,result.Value.AcceptedLanguages);service.Verify(s=>s.SendCampaignNotification(It.IsAny<Notification>(),It.IsAny<Guid[]>()),Times.Once);}
 [Fact]public async Task AnonymousFeedPagesCannotReadStaffCampaigns(){using var f=new Fixture();for(int i=1;i<=26;i++)f.App.Notifications.Add(new(){Id=i,Topic=i==26?"campaign_delivery":"all",CreatedDate=DateTime.UtcNow.Date,NotificationType=NotificationType.GlobalNotification});await f.App.SaveChangesAsync();var service=f.Notifications();Assert.Equal(20,(await service.GetNotifications(null)).Length);Assert.Equal(5,(await service.GetNotifications(null,page:1)).Length);await service.MarkAsRead(null,26);Assert.Equal(0,f.App.Notifications.Single(n=>n.Id==26).NotLoggedInReadCount);}
